mapper.select:
SELECT max(AUTHORIZE_LIMIT_AMT) AUTHORIZE_LIMIT_AMT, max(AUTHORIZE_TYPE) AUTHORIZE_TYPE FROM RSK_AUTHORIZE_MNG
WHERE 1=1

	and AUTHORIZE_TYPE IN (#{AUTHORIZE_TYPE_02}, #{AUTHORIZE_TYPE_03})

AND (TRADE_DIRECTION IS NULL


        OR TRADE_DIRECTION = #{tradeDirection}


)

  AND (ASSET_SEC_TYPE IS NULL OR ASSET_SEC_TYPE = #{assetSecType})


    AND (TRADE_MARKET IS NULL OR TRADE_MARKET = #{tradeMarket})

AND ASSET_TYPE = #{assetType}
AND USER_NAME = #{userName}

select
    ORDER_ID, SETTLE_DATE, MY_ACCT_NO, PS, COUNTER_ACCT_NO, SETTLE_AMT
from
    STL_PAY_ORDERS
where 
    (MY_ACCT_NO = #{acctId} or COUNTER_ACCT_NO = #{acctId})
    and ORDER_STATUS = #{ORDER_STATUS}
    and CCY = #{ccy}
    and PORTFOLIO_ID = #{portfolioId}
    and SETTLE_DATE = #{cdate,jdbcType=DATE}

select
    ORDER_ID, SETTLE_DATE, MY_ACCT_NO, PS, COUNTER_ACCT_NO, SETTLE_AMT
from
    STL_DVP_ORDERS
where 
    (MY_ACCT_NO = #{acctId} or COUNTER_ACCT_NO = #{acctId})
    and ORDER_STATUS = #{ORDER_STATUS}
    and CCY = #{ccy}
    and PORTFOLIO_ID = #{portfolioId}
    and SETTLE_DATE = #{cdate,jdbcType=DATE}

SELECT * FROM( SELECT MEQ.EXCHARGE_CODE exchargeCode, MEQ.TRADE_DATE tradeDate, MEQ.DATASOURCE_TYPE datasourceType, MEQ.OPEN_PRICE openPrice, MEQ.CLOSE_PRICE closePrice, MEQ.HIGH_PRICE highPrice, MEQ.LOW_PRICE lowPrice, MEQ.MID_PRICE midPrice, MEQ.BASIS_CYY basisCyy, MEQ.QUOT_CYY quotCyy, MEQ.QUOT_UNIT quotUnit, MEQ.INPUT_TYPE inputType FROM MST_EXCHARGE_QUOTE MEQ WHERE 1=1
AND MEQ.BASIS_CYY =#{basicCny}
AND MEQ.QUOT_CYY =#{offreCny}
AND MEQ.DATASOURCE_TYPE=#{valuation}
AND MEQ.TRADE_DATE < =#{serchDate}
ORDER BY MEQ.TRADE_DATE DESC ) WHERE ROWNUM = 1
